      out.write("        };\r\n");
      out.write("        const ORDER_STATUS_FILTERS = [\r\n");
      out.write("            { key: 'all', label: 'Tất cả', badge: 'secondary' },\r\n");
      out.write("            { key: 'new', label: 'Đơn hàng mới', badge: 'info' },\r\n");
      out.write("            { key: 'confirmed', label: 'Đã xác nhận', badge: 'primary' },\r\n");
      out.write("            { key: 'shipping', label: 'Đang giao', badge: 'warning' },\r\n");
      out.write("            { key: 'delivered', label: 'Đã giao', badge: 'success' },\r\n");
      out.write("            { key: 'cancelled', label: 'Đã hủy', badge: 'danger' },\r\n");
      out.write("            { key: 'failed', label: 'Giao that bai', badge: 'danger' },\r\n");
      out.write("            { key: 'returned', label: 'Hoàn trả / Hoàn tiền', badge: 'dark' }\r\n");
      out.write("        ];\r\n");
      out.write("        const orderHistoryState = {\r\n");
      out.write("            status: 'all',\r\n");
      out.write("            orders: []\r\n");
      out.write("        };\r\n");
      out.write("        const AUTH_STORAGE_KEY = 'auth_token';\r\n");
      out.write("        function getAuthToken() {\r\n");
      out.write("            const raw = localStorage.getItem(AUTH_STORAGE_KEY);\r\n");
      out.write("            if (!raw) {\r\n");
      out.write("                return null;\r\n");
      out.write("            }\r\n");
      out.write("            const trimmed = raw.trim();\r\n");
      out.write("            return trimmed.length > 0 && trimmed !== 'null' && trimmed !== 'undefined' ? trimmed : null;\r\n");
      out.write("        }\r\n");
      out.write("        function buildAuthHeaders(base) {\r\n");
      out.write("            const headers = Object.assign({}, base || {});\r\n");
      out.write("            const token = getAuthToken();\r\n");
      out.write("            if (token && !headers.Authorization) {\r\n");
      out.write("                headers.Authorization = 'Bearer ' + token;\r\n");
      out.write("            }\r\n");
      out.write("            return headers;\r\n");
      out.write("        }\r\n");
      out.write("        const favoritesState = {\r\n");
      out.write("            data: [],\r\n");
      out.write("            loading: false\r\n");
      out.write("        };\r\n");
      out.write("        const recentViewsState = {\r\n");
      out.write("            data: [],\r\n");
      out.write("            loading: false\r\n");
      out.write("        };\r\n");
      out.write("        const couponsState = {\r\n");
      out.write("            data: [],\r\n");
      out.write("            loading: false\r\n");
      out.write("        };\r\n");
      out.write("        let orderDetailModal = null;\r\n");
      out.write("        let reviewModal = null;\r\n");
      out.write("        const reviewState = {\r\n");
      out.write("            bookId: null,\r\n");
      out.write("            orderId: null,\r\n");
      out.write("            orderItemId: null,\r\n");
      out.write("            orderCode: '',\r\n");
      out.write("            bookTitle: '',\r\n");
      out.write("            loading: false,\r\n");
      out.write("            initialMediaUrl: null,\r\n");
      out.write("            initialMediaType: null,\r\n");
      out.write("            mediaUrl: null,\r\n");
      out.write("            mediaType: null,\r\n");
      out.write("            mediaFile: null,\r\n");
      out.write("            previewObjectUrl: null,\r\n");
      out.write("            removeMedia: false,\r\n");
      out.write("            reviewId: null\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        // Check authentication on page load\r\n");
      out.write("        document.addEventListener('DOMContentLoaded', function() {\r\n");
      out.write("            const token = localStorage.getItem('auth_token');\r\n");
      out.write("            if (!token) {\r\n");
      out.write("                // Redirect to login if not authenticated\r\n");
      out.write("                alert('Vui lòng đăng nhập để truy cập trang này.');\r\n");
      out.write("                window.location.href = `${contextPath}/login.jsp`;\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            \r\n");
      out.write("            const modalEl = document.getElementById('orderDetailModal');\r\n");
      out.write("            if (modalEl) {\r\n");
      out.write("                orderDetailModal = new bootstrap.Modal(modalEl);\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const reviewModalEl = document.getElementById('reviewModal');\r\n");
      out.write("            if (reviewModalEl) {\r\n");
      out.write("                reviewModal = new bootstrap.Modal(reviewModalEl);\r\n");
      out.write("                reviewModalEl.addEventListener('hidden.bs.modal', () => {\r\n");
      out.write("                    resetReviewForm();\r\n");
      out.write("                    reviewState.bookId = null;\r\n");
      out.write("                    reviewState.orderId = null;\r\n");
      out.write("                    reviewState.orderItemId = null;\r\n");
      out.write("                    reviewState.orderCode = '';\r\n");
      out.write("                    reviewState.bookTitle = '';\r\n");
      out.write("                });\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const reviewMediaInput = document.getElementById('reviewMediaInput');\r\n");
      out.write("            if (reviewMediaInput) {\r\n");
      out.write("                reviewMediaInput.addEventListener('change', handleReviewMediaInputChange);\r\n");
      out.write("            }\r\n");
      out.write("            const reviewMediaRemoveBtn = document.getElementById('reviewMediaRemoveBtn');\r\n");
      out.write("            if (reviewMediaRemoveBtn) {\r\n");
      out.write("                reviewMediaRemoveBtn.addEventListener('click', handleReviewMediaRemove);\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            loadUserProfile();\r\n");
      out.write("            initAddressManager();\r\n");
      out.write("            initOrderHistoryFilters();\r\n");
      out.write("            loadOrderHistory();\r\n");
      out.write("            loadFavorites();\r\n");
      out.write("            loadRecentViews();\r\n");
      out.write("            loadUserCoupons();\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Profile form submission\r\n");
      out.write("        document.getElementById('profileForm').addEventListener('submit', function(e) {\r\n");
      out.write("            e.preventDefault();\r\n");
      out.write("            updateProfile();\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Change password form submission\r\n");
      out.write("        document.getElementById('changePasswordForm').addEventListener('submit', function(e) {\r\n");
      out.write("            e.preventDefault();\r\n");
      out.write("            changePassword();\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        // Delete account form submission\r\n");
      out.write("        document.getElementById('deleteAccountForm').addEventListener('submit', function(e) {\r\n");
      out.write("            e.preventDefault();\r\n");
      out.write("            deleteAccount();\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        document.getElementById('reviewForm').addEventListener('submit', function (event) {\r\n");
      out.write("            event.preventDefault();\r\n");
      out.write("            submitReview();\r\n");
      out.write("        });\r\n");
      out.write("\r\n");
      out.write("        function loadUserProfile() {\r\n");
      out.write("            const token = localStorage.getItem('auth_token');\r\n");
      out.write("            fetch(`${contextPath}/api/profile`, {\r\n");
      out.write("                headers: {\r\n");
      out.write("                    'Authorization': 'Bearer ' + token\r\n");
      out.write("                }\r\n");
      out.write("            })\r\n");
      out.write("                .then(response => response.json())\r\n");
      out.write("                .then(data => {\r\n");
      out.write("                    if (data.success) {\r\n");
      out.write("                        currentUser = data.user;\r\n");
      out.write("                        document.getElementById('fullName').value = data.user.fullName || '';\r\n");
      out.write("                        document.getElementById('email').value = data.user.email || '';\r\n");
      out.write("                        document.getElementById('phone').value = data.user.phone || '';\r\n");
      out.write("                        document.getElementById('birthDate').value = data.user.birthDate || '';\r\n");
      out.write("                        document.getElementById('address').value = data.user.address || '';\r\n");
      out.write("                    } else {\r\n");
      out.write("                        showAlert('Không thể tải thông tin profile: ' + data.message, 'danger');\r\n");
      out.write("                        if (data.message === 'Not authenticated') {\r\n");
      out.write("                            window.location.href = `${contextPath}/login.jsp`;\r\n");
      out.write("                        }\r\n");
      out.write("                    }\r\n");
      out.write("                })\r\n");
