      out.write("                const percentValue = Number.isFinite(rawValue) ? rawValue : 0;\r\n");
      out.write("                const rawMaxDiscount = Number(coupon.maxDiscount);\r\n");
      out.write("                const hasMaxDiscount = Number.isFinite(rawMaxDiscount) && rawMaxDiscount > 0;\r\n");
      out.write("                const discountLine = coupon.type === 'percentage'\r\n");
      out.write("                    ? `Giảm ${percentValue.toLocaleString('vi-VN')}%${hasMaxDiscount ? ` (tối đa ${formatCurrency(coupon.maxDiscount)})` : ''}`\r\n");
      out.write("                    : `Giảm ${formatCurrency(coupon.value)}`;\r\n");
      out.write("                const minimumOrderLine = coupon.minimumOrder && Number(coupon.minimumOrder) > 0\r\n");
      out.write("                    ? `<div class=\"text-muted small\">Đơn tối thiểu: ${formatCurrency(coupon.minimumOrder)}</div>`\r\n");
      out.write("                    : '';\r\n");
      out.write("                let validityLine = '';\r\n");
      out.write("                if (coupon.startDate || coupon.endDate) {\r\n");
      out.write("                    const start = coupon.startDate ? formatDate(coupon.startDate) : 'Bất kỳ';\r\n");
      out.write("                    const end = coupon.endDate ? formatDate(coupon.endDate) : 'Không giới hạn';\r\n");
      out.write("                    validityLine = `<div class=\"text-muted small\">Hiệu lực: ${start} - ${end}</div>`;\r\n");
      out.write("                }\r\n");
      out.write("                const userStatus = (coupon.userStatus || '').toLowerCase();\r\n");
      out.write("                let statusBadge = '<span class=\"badge bg-success\">Sẵn sàng sử dụng</span>';\r\n");
      out.write("                if (userStatus === 'used') {\r\n");
      out.write("                    statusBadge = '<span class=\"badge bg-secondary\">Đã sử dụng</span>';\r\n");
      out.write("                } else if (userStatus === 'expired') {\r\n");
      out.write("                    statusBadge = '<span class=\"badge bg-danger\">Hết hạn</span>';\r\n");
      out.write("                } else if (coupon.endDate) {\r\n");
      out.write("                    const endDate = new Date(coupon.endDate);\r\n");
      out.write("                    if (!Number.isNaN(endDate.getTime()) && endDate < now) {\r\n");
      out.write("                        statusBadge = '<span class=\"badge bg-danger\">Hết hạn</span>';\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("                return `\r\n");
      out.write("                    <div class=\"card shadow-sm mb-3\">\r\n");
      out.write("                        <div class=\"card-body d-flex flex-column flex-md-row justify-content-between align-items-start gap-3\">\r\n");
      out.write("                            <div>\r\n");
      out.write("                                <h5 class=\"card-title mb-1\">${escapeHtml(coupon.code)}</h5>\r\n");
      out.write("                                ${coupon.description ? `<p class=\"mb-2 text-muted\">${escapeHtml(coupon.description)}</p>` : ''}\r\n");
      out.write("                                <div class=\"small text-muted\">${discountLine}</div>\r\n");
      out.write("                                ${minimumOrderLine}\r\n");
      out.write("                                ${validityLine}\r\n");
      out.write("                            </div>\r\n");
      out.write("                            <div class=\"ms-md-auto\">${statusBadge}</div>\r\n");
      out.write("                        </div>\r\n");
      out.write("                    </div>\r\n");
      out.write("                `;\r\n");
      out.write("            }).join('');\r\n");
      out.write("\r\n");
      out.write("            container.innerHTML = html;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function initAddressManager() {\r\n");
      out.write("            addressState.listContainer = document.getElementById('addressListContainer');\r\n");
      out.write("            addressState.emptyStateEl = document.getElementById('addressEmptyState');\r\n");
      out.write("            addressState.loadingMessageEl = document.getElementById('addressListLoading');\r\n");
      out.write("            addressState.errorMessageEl = document.getElementById('addressListError');\r\n");
      out.write("            addressState.form = document.getElementById('addressForm');\r\n");
