      out.write("        function handleAddressListClick(event) {\r\n");
      out.write("            const actionBtn = event.target.closest('[data-action]');\r\n");
      out.write("            if (!actionBtn) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const addressCard = actionBtn.closest('[data-address-id]');\r\n");
      out.write("            if (!addressCard) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
