      out.write("                    break;\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        async function loadAddresses() {\r\n");
      out.write("            if (!addressState.listContainer) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            addressState.loading = true;\r\n");
      out.write("            renderAddressList();\r\n");
      out.write("\r\n");
      out.write("            const token = localStorage.getItem('auth_token');\r\n");
      out.write("            if (!token) {\r\n");
      out.write("                addressState.error = 'Bạn cần đăng nhập để xem địa chỉ.';\r\n");
      out.write("                addressState.loading = false;\r\n");
      out.write("                renderAddressList();\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            try {\r\n");
      out.write("                const response = await fetch(`${contextPath}/api/profile/addresses`, {\r\n");
      out.write("                    headers: {\r\n");
      out.write("                        'Authorization': 'Bearer ' + token\r\n");
      out.write("                    }\r\n");
      out.write("                });\r\n");
      out.write("                if (response.status === 401) {\r\n");
      out.write("                    addressState.loading = false;\r\n");
      out.write("                    renderAddressList();\r\n");
      out.write("                    window.location.href = `${contextPath}/login.jsp`;\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("                const data = await response.json();\r\n");
      out.write("                if (response.ok && data.success) {\r\n");
      out.write("                    addressState.addressList = Array.isArray(data.addresses) ? data.addresses : [];\r\n");
      out.write("                    addressState.error = null;\r\n");
      out.write("                } else {\r\n");
      out.write("                    addressState.error = data.message || 'Không thể tải danh sách địa chỉ.';\r\n");
      out.write("                }\r\n");
      out.write("            } catch (error) {\r\n");
      out.write("                console.error('Error loading addresses:', error);\r\n");
      out.write("                addressState.error = 'Lỗi kết nối. Vui lòng thử lại.';\r\n");
      out.write("            } finally {\r\n");
      out.write("                addressState.loading = false;\r\n");
      out.write("                renderAddressList();\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function renderAddressList() {\r\n");
      out.write("            if (!addressState.listContainer || !addressState.emptyStateEl || !addressState.loadingMessageEl || !addressState.errorMessageEl) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            addressState.listContainer.innerHTML = '';\r\n");
      out.write("            addressState.emptyStateEl.classList.add('d-none');\r\n");
      out.write("            addressState.loadingMessageEl.classList.add('d-none');\r\n");
      out.write("            addressState.errorMessageEl.classList.add('d-none');\r\n");
      out.write("\r\n");
      out.write("            if (addressState.loading) {\r\n");
      out.write("                addressState.loadingMessageEl.classList.remove('d-none');\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            if (addressState.error) {\r\n");
      out.write("                addressState.errorMessageEl.textContent = addressState.error;\r\n");
      out.write("                addressState.errorMessageEl.classList.remove('d-none');\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            if (addressState.addressList.length === 0) {\r\n");
      out.write("                addressState.emptyStateEl.classList.remove('d-none');\r\n");
