      out.write("\r\n");
      out.write("        function buildAddressCard(address) {\r\n");
      out.write("            const card = document.createElement('div');\r\n");
      out.write("            card.className = 'card mb-3';\r\n");
      out.write("            card.setAttribute('data-address-id', address.id);\r\n");
