      out.write("\r\n");
      out.write("            const addressLines = [\r\n");
      out.write("                address.line1,\r\n");
      out.write("                address.line2,\r\n");
      out.write("                address.ward,\r\n");
      out.write("                address.district,\r\n");
      out.write("                address.city,\r\n");
      out.write("                address.province,\r\n");
      out.write("                address.postalCode,\r\n");
      out.write("                address.country\r\n");
      out.write("            ]\r\n");
      out.write("                .filter(part => part && part.trim())\r\n");
      out.write("                .join(', ');\r\n");
      out.write("\r\n");
      out.write("            const noteSection = address.note ? `\r\n");
      out.write("                <p class=\"mb-0 text-muted\"><small>Ghi chú: ${escapeHtml(address.note)}</small></p>\r\n");
      out.write("            ` : '';\r\n");
      out.write("\r\n");
      out.write("            const defaultButton = address.isDefault ? '' : `\r\n");
      out.write("                <button class=\"btn btn-sm btn-outline-primary me-2\" data-action=\"set-default\">Đặt mặc định</button>\r\n");
      out.write("            `;\r\n");
      out.write("\r\n");
      out.write("            card.innerHTML = `\r\n");
      out.write("                <div class=\"card-body d-flex flex-column flex-md-row justify-content-between align-items-start\">\r\n");
      out.write("                    <div class=\"me-md-3\">\r\n");
      out.write("                        <div class=\"d-flex align-items-center mb-1\">\r\n");
      out.write("                            <h6 class=\"mb-0\">${escapeHtml(address.recipientName)}</h6>\r\n");
      out.write("                            ${headerBadges.join('')}\r\n");
      out.write("                        </div>\r\n");
      out.write("                        <p class=\"mb-1 text-muted\">${escapeHtml(address.phone)}</p>\r\n");
      out.write("                        <p class=\"mb-1\">${escapeHtml(addressLines)}</p>\r\n");
      out.write("                        ${noteSection}\r\n");
      out.write("                    </div>\r\n");
      out.write("                    <div class=\"mt-3 mt-md-0 text-md-end\">\r\n");
      out.write("                        ${defaultButton}\r\n");
      out.write("                        <button class=\"btn btn-sm btn-outline-secondary me-2\" data-action=\"edit\">Sửa</button>\r\n");
      out.write("                        <button class=\"btn btn-sm btn-outline-danger\" data-action=\"delete\">Xóa</button>\r\n");
      out.write("                    </div>\r\n");
      out.write("                </div>\r\n");
      out.write("            `;\r\n");
      out.write("\r\n");
      out.write("            return card;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function openAddressModal(addressId) {\r\n");
      out.write("            addressState.selectedAddressId = addressId ?? null;\r\n");
      out.write("            if (!addressState.formModal || !addressState.form) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const modalTitle = document.getElementById('addressModalTitle');\r\n");
      out.write("            if (modalTitle) {\r\n");
      out.write("                modalTitle.textContent = addressId ? 'Cập nhật địa chỉ' : 'Thêm địa chỉ mới';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const submitBtn = document.getElementById('addressSubmitBtn');\r\n");
      out.write("            if (submitBtn) {\r\n");
      out.write("                submitBtn.textContent = addressId ? 'Cập nhật' : 'Thêm mới';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            if (addressId) {\r\n");
      out.write("                const address = addressState.addressList.find(item => item.id === addressId);\r\n");
      out.write("                if (address) {\r\n");
      out.write("                    populateAddressForm(address);\r\n");
      out.write("                } else {\r\n");
      out.write("                    showAlert('Không tìm thấy địa chỉ đã chọn.', 'danger');\r\n");
      out.write("                    addressState.selectedAddressId = null;\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("            } else {\r\n");
      out.write("                resetAddressForm();\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            addressState.formModal.show();\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function populateAddressForm(address) {\r\n");
      out.write("            if (!addressState.form) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            const elements = addressState.form.elements;\r\n");
      out.write("            elements['label'].value = address.label || '';\r\n");
      out.write("            elements['recipientName'].value = address.recipientName || '';\r\n");
      out.write("            elements['phone'].value = address.phone || '';\r\n");
      out.write("            elements['line1'].value = address.line1 || '';\r\n");
      out.write("            elements['line2'].value = address.line2 || '';\r\n");
      out.write("            elements['ward'].value = address.ward || '';\r\n");
      out.write("            elements['district'].value = address.district || '';\r\n");
      out.write("            elements['city'].value = address.city || '';\r\n");
      out.write("            elements['province'].value = address.province || '';\r\n");
      out.write("            elements['postalCode'].value = address.postalCode || '';\r\n");
      out.write("            elements['country'].value = address.country || 'Việt Nam';\r\n");
      out.write("            elements['note'].value = address.note || '';\r\n");
      out.write("            elements['isDefault'].checked = Boolean(address.isDefault);\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function resetAddressForm() {\r\n");
      out.write("            if (!addressState.form) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            addressState.form.reset();\r\n");
      out.write("            addressState.selectedAddressId = null;\r\n");
      out.write("            const errorEl = document.getElementById('addressFormError');\r\n");
      out.write("            if (errorEl) {\r\n");
      out.write("                errorEl.classList.add('d-none');\r\n");
      out.write("                errorEl.textContent = '';\r\n");
      out.write("            }\r\n");
      out.write("            const submitBtn = document.getElementById('addressSubmitBtn');\r\n");
      out.write("            if (submitBtn) {\r\n");
      out.write("                submitBtn.textContent = 'Thêm mới';\r\n");
      out.write("            }\r\n");
      out.write("            const modalTitle = document.getElementById('addressModalTitle');\r\n");
      out.write("            if (modalTitle) {\r\n");
      out.write("                modalTitle.textContent = 'Thêm địa chỉ';\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        async function handleAddressSubmit(event) {\r\n");
      out.write("            event.preventDefault();\r\n");
      out.write("            if (!addressState.form) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const submitBtn = addressState.form.querySelector('button[type=\"submit\"]');\r\n");
      out.write("            const errorEl = document.getElementById('addressFormError');\r\n");
      out.write("            if (errorEl) {\r\n");
      out.write("                errorEl.classList.add('d-none');\r\n");
      out.write("                errorEl.textContent = '';\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const formData = new FormData(addressState.form);\r\n");
      out.write("            const payload = {};\r\n");
      out.write("            formData.forEach((value, key) => {\r\n");
      out.write("                if (key === 'isDefault') {\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("                payload[key] = typeof value === 'string' ? value.trim() : value;\r\n");
      out.write("            });\r\n");
      out.write("            payload.isDefault = formData.get('isDefault') === 'on';\r\n");
      out.write("\r\n");
      out.write("            if (!payload.recipientName || !payload.phone || !payload.line1) {\r\n");
      out.write("                showFormError('Vui lòng nhập đầy đủ tên người nhận, số điện thoại và địa chỉ.');\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const token = localStorage.getItem('auth_token');\r\n");
      out.write("            if (!token) {\r\n");
      out.write("                showFormError('Bạn cần đăng nhập để lưu địa chỉ.');\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            const addressId = addressState.selectedAddressId;\r\n");
      out.write("            const url = addressId ? `${contextPath}/api/profile/addresses/${addressId}` : `${contextPath}/api/profile/addresses`;\r\n");
      out.write("            const method = addressId ? 'PUT' : 'POST';\r\n");
      out.write("\r\n");
      out.write("            if (submitBtn) {\r\n");
      out.write("                submitBtn.disabled = true;\r\n");
      out.write("            }\r\n");
      out.write("\r\n");
      out.write("            try {\r\n");
      out.write("                const response = await fetch(url, {\r\n");
      out.write("                    method,\r\n");
      out.write("                    headers: {\r\n");
      out.write("                        'Content-Type': 'application/json',\r\n");
      out.write("                        'Authorization': 'Bearer ' + token\r\n");
      out.write("                    },\r\n");
      out.write("                    body: JSON.stringify(payload)\r\n");
      out.write("                });\r\n");
      out.write("                const data = await response.json().catch(() => ({}));\r\n");
      out.write("                if (response.status === 401 || data.message === 'Not authenticated') {\r\n");
      out.write("                    addressState.formModal?.hide();\r\n");
      out.write("                    showAlert('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.', 'warning');\r\n");
      out.write("                    window.location.href = `${contextPath}/login.jsp`;\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("                if (response.ok && data.success) {\r\n");
      out.write("                    addressState.formModal?.hide();\r\n");
      out.write("                    showAlert(addressId ? 'Đã cập nhật địa chỉ' : 'Đã thêm địa chỉ mới', 'success');\r\n");
      out.write("                    await loadAddresses();\r\n");
