      out.write("        function escapeHtml(value) {\r\n");
      out.write("            if (typeof value !== 'string') {\r\n");
      out.write("                return value ?? '';\r\n");
      out.write("            }\r\n");
      out.write("            return value\r\n");
      out.write("                .replace(/&/g, '&amp;')\r\n");
      out.write("                .replace(/</g, '&lt;')\r\n");
      out.write("                .replace(/>/g, '&gt;')\r\n");
      out.write("                .replace(/\"/g, '&quot;')\r\n");
      out.write("                .replace(/'/g, '&#39;');\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function getStatusMeta(status) {\r\n");
      out.write("            if (!status) {\r\n");
      out.write("                return { key: 'unknown', label: 'Không xác định', badge: 'secondary' };\r\n");
      out.write("            }\r\n");
      out.write("            const normalized = String(status).toLowerCase();\r\n");
      out.write("            const predefined = ORDER_STATUS_FILTERS.find(item => item.key === normalized);\r\n");
      out.write("            if (predefined) {\r\n");
      out.write("                return { key: predefined.key, label: predefined.label, badge: predefined.badge };\r\n");
      out.write("            }\r\n");
      out.write("            switch (normalized) {\r\n");
      out.write("                case 'completed':\r\n");
      out.write("                    return { key: 'completed', label: 'Hoàn tất', badge: 'success' };\r\n");
      out.write("                case 'pending':\r\n");
      out.write("                    return { key: 'pending', label: 'Đang xử lý', badge: 'warning' };\r\n");
      out.write("                case 'cancelled':\r\n");
