      out.write("                default:\r\n");
      out.write("                    return { key: normalized, label: normalized.charAt(0).toUpperCase() + normalized.slice(1), badge: 'secondary' };\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
