      out.write("            return number.toLocaleString('vi-VN') + 'đ';\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function normalizeToDate(value) {\r\n");
      out.write("            if (!value) {\r\n");
      out.write("                return null;\r\n");
      out.write("            }\r\n");
      out.write("            if (value instanceof Date) {\r\n");
      out.write("                return Number.isNaN(value.getTime()) ? null : value;\r\n");
      out.write("            }\r\n");
      out.write("            if (typeof value === 'string' || typeof value === 'number') {\r\n");
      out.write("                const fromPrimitive = new Date(value);\r\n");
      out.write("                if (!Number.isNaN(fromPrimitive.getTime())) {\r\n");
      out.write("                    return fromPrimitive;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("            if (Array.isArray(value)) {\r\n");
      out.write("                const [year, month, day, hour = 0, minute = 0, second = 0, nano = 0] = value;\r\n");
      out.write("                if (Number.isFinite(year) && Number.isFinite(month) && Number.isFinite(day)) {\r\n");
      out.write("                    const fromArray = new Date(year, month - 1, day, hour, minute, second, Math.floor(nano / 1e6));\r\n");
      out.write("                    if (!Number.isNaN(fromArray.getTime())) {\r\n");
      out.write("                        return fromArray;\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("            if (typeof value === 'object') {\r\n");
      out.write("                const dateSource = value.date && typeof value.date === 'object' ? value.date : value;\r\n");
      out.write("                const timeSource = value.time && typeof value.time === 'object' ? value.time : value;\r\n");
      out.write("                const resolveMonth = input => {\r\n");
      out.write("                    if (Number.isFinite(input)) {\r\n");
      out.write("                        return input;\r\n");
      out.write("                    }\r\n");
      out.write("                    if (typeof input === 'string') {\r\n");
      out.write("                        const monthNames = ['JANUARY', 'FEBRUARY', 'MARCH', 'APRIL', 'MAY', 'JUNE', 'JULY', 'AUGUST', 'SEPTEMBER', 'OCTOBER', 'NOVEMBER', 'DECEMBER'];\r\n");
      out.write("                        const normalized = input.toUpperCase();\r\n");
      out.write("                        const index = monthNames.indexOf(normalized);\r\n");
      out.write("                        if (index !== -1) {\r\n");
      out.write("                            return index + 1;\r\n");
      out.write("                        }\r\n");
      out.write("                        const parsed = parseInt(normalized, 10);\r\n");
      out.write("                        if (Number.isFinite(parsed)) {\r\n");
      out.write("                            return parsed;\r\n");
      out.write("                        }\r\n");
      out.write("                    }\r\n");
      out.write("                    return null;\r\n");
      out.write("                };\r\n");
      out.write("                const toNumber = input => (Number.isFinite(input) ? input : parseInt(input, 10));\r\n");
      out.write("                const year = toNumber(dateSource.year);\r\n");
      out.write("                const month = resolveMonth(dateSource.monthValue ?? dateSource.month);\r\n");
      out.write("                const day = toNumber(dateSource.day ?? dateSource.dayOfMonth);\r\n");
      out.write("                if (Number.isFinite(year) && Number.isFinite(month) && Number.isFinite(day)) {\r\n");
      out.write("                    const hour = toNumber(timeSource.hour) || 0;\r\n");
      out.write("                    const minute = toNumber(timeSource.minute) || 0;\r\n");
      out.write("                    const second = toNumber(timeSource.second) || 0;\r\n");
      out.write("                    const nano = toNumber(timeSource.nano) || 0;\r\n");
      out.write("                    const fromObject = new Date(year, month - 1, day, hour, minute, second, Math.floor(nano / 1e6));\r\n");
      out.write("                    if (!Number.isNaN(fromObject.getTime())) {\r\n");
      out.write("                        return fromObject;\r\n");
      out.write("                    }\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("            return null;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function formatDate(value) {\r\n");
      out.write("            const date = normalizeToDate(value);\r\n");
      out.write("            return date ? date.toLocaleDateString('vi-VN') : '';\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        function formatDateTime(value) {\r\n");
      out.write("            const date = normalizeToDate(value);\r\n");
      out.write("            return date ? date.toLocaleString('vi-VN') : '';\r\n");
      out.write("        }\r\n");
