      out.write("            try {\r\n");
      out.write("                const [orderResponse, timelineResponse] = await Promise.all([\r\n");
      out.write("                    fetch(`${contextPath}/api/profile/orders/${orderId}`, {\r\n");
      out.write("                        headers: { 'Authorization': 'Bearer ' + token }\r\n");
      out.write("                    }),\r\n");
      out.write("                    fetch(`${contextPath}/api/profile/orders/${orderId}/timeline`, {\r\n");
      out.write("                        headers: { 'Authorization': 'Bearer ' + token }\r\n");
      out.write("                    })\r\n");
      out.write("                ]);\r\n");
      out.write("                const orderPayload = await orderResponse.json();\r\n");
      out.write("                const timelinePayload = await timelineResponse.json();\r\n");
      out.write("                if (!orderResponse.ok || !orderPayload.success) {\r\n");
      out.write("                    throw new Error(orderPayload.message || 'Không thể tải chi tiết đơn hàng.');\r\n");
      out.write("                }\r\n");
      out.write("                if (!timelineResponse.ok || !timelinePayload.success) {\r\n");
      out.write("                    throw new Error(timelinePayload.message || 'Không thể tải tiến trình đơn hàng.');\r\n");
      out.write("                }\r\n");
      out.write("                renderOrderDetail(orderPayload.order, Array.isArray(timelinePayload.timeline) ? timelinePayload.timeline : []);\r\n");
      out.write("            } catch (error) {\r\n");
      out.write("                console.error('viewOrderDetails error', error);\r\n");
      out.write("                if (container) {\r\n");
      out.write("                    container.innerHTML = `<div class=\"alert alert-danger\">${escapeHtml(error.message || 'Không thể tải chi tiết đơn hàng')}</div>`;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        async function requestCancelOrder(orderId, orderCode, triggerButton) {\r\n");
      out.write("            if (!orderId) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            const token = localStorage.getItem('auth_token');\r\n");
      out.write("            if (!token) {\r\n");
      out.write("                showAlert('Bạn cần đăng nhập để hủy đơn hàng.', 'warning');\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            const confirmMessage = orderCode ? `Bạn có chắc chắn muốn hủy đơn ${orderCode}?` : 'Bạn có chắc chắn muốn hủy đơn hàng này?';\r\n");
      out.write("            if (!confirm(confirmMessage)) {\r\n");
      out.write("                return;\r\n");
      out.write("            }\r\n");
      out.write("            let reason = prompt('Nhập lý do hủy đơn (có thể bỏ trống):');\r\n");
      out.write("            if (reason) {\r\n");
      out.write("                reason = reason.trim();\r\n");
      out.write("                if (reason.length > 255) {\r\n");
      out.write("                    reason = reason.substring(0, 255);\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("            if (triggerButton) {\r\n");
      out.write("                triggerButton.disabled = true;\r\n");
      out.write("                triggerButton.dataset.originalHtml = triggerButton.innerHTML;\r\n");
      out.write("                triggerButton.innerHTML = '<span class=\"spinner-border spinner-border-sm me-2\"></span>Đang hủy...';\r\n");
      out.write("            }\r\n");
      out.write("            try {\r\n");
      out.write("                const response = await fetch(`${contextPath}/api/profile/orders/${orderId}/cancel`, {\r\n");
      out.write("                    method: 'POST',\r\n");
      out.write("                    headers: {\r\n");
      out.write("                        'Content-Type': 'application/json',\r\n");
      out.write("                        'Authorization': 'Bearer ' + token\r\n");
      out.write("                    },\r\n");
      out.write("                    body: JSON.stringify({ reason: reason || null })\r\n");
      out.write("                });\r\n");
      out.write("                const payload = await response.json().catch(() => ({ success: false }));\r\n");
      out.write("                if (!response.ok || !payload.success) {\r\n");
      out.write("                    const message = payload && payload.message ? payload.message : 'Không thể hủy đơn hàng. Vui lòng thử lại.';\r\n");
      out.write("                    showAlert(message, 'danger');\r\n");
      out.write("                    return;\r\n");
      out.write("                }\r\n");
      out.write("                showAlert(payload.message || 'Đã hủy đơn hàng.', 'success');\r\n");
      out.write("                loadOrderHistory();\r\n");
      out.write("                viewOrderDetails(orderId);\r\n");
      out.write("            } catch (error) {\r\n");
      out.write("                console.error('requestCancelOrder error', error);\r\n");
      out.write("                showAlert('Không thể hủy đơn hàng. Vui lòng thử lại sau.', 'danger');\r\n");
      out.write("            } finally {\r\n");
      out.write("                if (triggerButton) {\r\n");
      out.write("                    const original = triggerButton.dataset.originalHtml;\r\n");
      out.write("                    triggerButton.innerHTML = original || '<i class=\"fas fa-times me-1\"></i>Hủy đơn';\r\n");
      out.write("                    triggerButton.disabled = false;\r\n");
      out.write("                    delete triggerButton.dataset.originalHtml;\r\n");
      out.write("                }\r\n");
      out.write("            }\r\n");
      out.write("        }\r\n");
