      out.write("        function resolveReviewMediaUrl(url) {\r\n");
      out.write("            if (!url) {\r\n");
      out.write("                return null;\r\n");
      out.write("            }\r\n");
      out.write("            const trimmed = url.trim();\r\n");
      out.write("            if (!trimmed) {\r\n");
      out.write("                return null;\r\n");
      out.write("            }\r\n");
      out.write("            if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('//')) {\r\n");
      out.write("                return trimmed;\r\n");
